CGAL::Arrangement_2<CGAL::Simple_cartesian<double>>::Face_handle face = arrangement.faces_begin();
for (const Segment2d& seg : segments) {
    Point2d from = seg.p1();
    Point2d to = seg.p2();
    CK::Segment_2 cgalSeg(CK_Point_2(from.x(), from.y()), CK_Point_2(to.x(), to.y()));
    insert(arrangement, cgalSeg);
}
return arrangement;

